parser = argparse.ArgumentParser()
parser.add_argument("--apply", action="store_true", help="write the reviewed mention plan")
args = parser.parse_args()


def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def read_csv(path: Path):
    with path.open(encoding="utf-8-sig", newline="") as stream:
        reader = csv.DictReader(stream)
        return reader.fieldnames, list(reader)


def validate_overlap(a, b):
    if a["segment_id"] != b["segment_id"]:
        return
    a_start, a_end = int(a["start_char"]), int(a["end_char"])
    b_start, b_end = int(b["start_char"]), int(b["end_char"])
    if max(a_start, b_start) >= min(a_end, b_end):
        return
    nested = (
        a_start <= b_start and a_end >= b_end
    ) or (
        b_start <= a_start and b_end >= a_end
    )
    if not nested or a["candidate_id"] == b["candidate_id"]:
        raise SystemExit(
            f"invalid mention overlap: {a['segment_id']} "
            f"{a['surface_form']!r} / {b['surface_form']!r}"
        )


for rel, expected in EXPECTED_HASHES.items():
    path = ROOT / rel
    actual = sha256(path)
    if actual != expected:
        raise SystemExit(f"input hash mismatch: {rel}: {actual}")

segment_rows = [
    json.loads(line)
    for line in SEGMENTS.read_text(encoding="utf-8").splitlines()
    if line.strip()
]
segments = {row["segment_id"]: row for row in segment_rows}
candidate_fields, candidate_rows = read_csv(CANDIDATES)
candidates = {row["candidate_id"]: row for row in candidate_rows}
fields, rows = read_csv(MENTIONS)
expected_fields = [
    "mention_id", "segment_id", "candidate_id", "surface_form",
    "start_char", "end_char", "note",
]
if fields != expected_fields:
    raise SystemExit(f"unexpected mentions.csv schema: {fields}")

existing_ids = {row["mention_id"] for row in rows}
existing_keys = {
    (row["segment_id"], int(row["start_char"]), int(row["end_char"]))
    for row in rows
}
planned = []
for item in PLAN:
    segment_id = item["segment_id"]
    candidate_id = item["candidate_id"]
    if segment_id not in segments:
        raise SystemExit(f"unknown segment: {segment_id}")
    if candidate_id not in candidates:
        raise SystemExit(f"unknown candidate: {candidate_id}")
    if candidates[candidate_id]["suggested_type"] not in ALLOWED_TYPES:
        raise SystemExit(f"candidate type is not an entity type: {candidate_id}")
    segment = segments[segment_id]
    source_path = ROOT / segment["source_file"]
    source_lines = source_path.read_text(encoding="utf-8-sig").splitlines()
    source_text = "\n".join(source_lines[segment["line_start"] - 1:segment["line_end"]])
    start = int(item["start_char"])
    end = int(item["end_char"])
    surface = item["surface_form"]
    if source_text[start:end] != surface:
        raise SystemExit(f"source span mismatch: {segment_id} {start}:{end} {surface!r}")
    natural_key = (segment_id, start, end)
    if natural_key in existing_keys:
        raise SystemExit(f"mention natural key already exists: {natural_key}")
    digest = hashlib.sha256(
        f"{segment_id}|{start}|{end}|{candidate_id}".encode("utf-8")
    ).hexdigest()[:16]
    mention_id = f"m-s2-surface-{digest}"
    if mention_id in existing_ids:
        raise SystemExit(f"mention ID already exists: {mention_id}")
    planned.append({
        "mention_id": mention_id,
        "segment_id": segment_id,
        "candidate_id": candidate_id,
        "surface_form": surface,
        "start_char": str(start),
        "end_char": str(end),
        "note": item["note"],
    })
    existing_ids.add(mention_id)
    existing_keys.add(natural_key)

for i, item in enumerate(planned):
    for other in planned[i + 1:]:
        validate_overlap(item, other)
for item in planned:
    for old in rows:
        validate_overlap({
            "segment_id": old["segment_id"],
            "candidate_id": old["candidate_id"],
            "surface_form": old["surface_form"],
            "start_char": int(old["start_char"]),
            "end_char": int(old["end_char"]),
        }, {
            "segment_id": item["segment_id"],
            "candidate_id": item["candidate_id"],
            "surface_form": item["surface_form"],
            "start_char": int(item["start_char"]),
            "end_char": int(item["end_char"]),
        })

print(f"filtered_prompt_count={FILTERED_PROMPT_COUNT}")
print(f"direct_accept_count={DIRECT_ACCEPT_COUNT}")
print(f"corrected_and_nested_count={CORRECTED_AND_NESTED_COUNT}")
print(f"planned_mentions={len(planned)}")
print(f"mentions_before={len(rows)}")
print(f"mentions_after={len(rows) + len(planned)}")
print(f"plan_sha256={hashlib.sha256(json.dumps(PLAN, ensure_ascii=False, sort_keys=True).encode('utf-8')).hexdigest()}")
if not args.apply:
    print("mode=dry-run; no files written")
    raise SystemExit(0)

recovery = Path(tempfile.gettempdir()) / (
    "pnp-s2-surface-mentions-" + datetime.now().strftime("%Y%m%d-%H%M%S")
)
recovery.mkdir(parents=True, exist_ok=False)
shutil.copy2(MENTIONS, recovery / MENTIONS.name)
print(f"recovery_copy={recovery / MENTIONS.name}")

raw = MENTIONS.read_bytes()
line_ending = "\r\n" if b"\r\n" in raw else "\n"
has_bom = raw.startswith(b"\xef\xbb\xbf")
encoding = "utf-8-sig" if has_bom else "utf-8"
with tempfile.NamedTemporaryFile(
    "w", encoding=encoding, newline="", dir=TABLES, delete=False
) as stream:
    writer = csv.DictWriter(stream, fieldnames=fields, lineterminator=line_ending)
    writer.writeheader()
    writer.writerows(rows)
    writer.writerows(planned)
    temporary = Path(stream.name)
temporary.replace(MENTIONS)
print(f"mentions_sha256_after={sha256(MENTIONS)}")
print(f"written_mentions={len(planned)}")
